import React from 'react';
// Assuming Tailwind CSS is set up in your project
// Removed useOutletContext import as it's no longer used
// import { useOutletContext } from 'react-router-dom';


// App component is rendered by the router within the App layout.
// It now receives necessary state and handlers as direct props from the parent (App/router config).
function App({
    videoUrl,
    handleInputChange,
    handleDownloadAndNavigate,
    isLoading,
    error,
    // Although results are shown on DownloadPage, these states are managed in App and passed to HomePage
    resultsOptions,
    resultsThumbnailUrl
}) {
  // Removed useOutletContext() call as props are used directly
  // const { ... } = useOutletContext();


  return (
    // Homepage Content (Downloader Interface)
    // This is rendered when path is '/' by the router
    <div className="flex flex-col items-center py-10 px-4 w-full">
      {/* Header Section */}
      <header className="text-center mb-8 mt-8 px-4">
        <h1 className="text-4xl md:text-5xl font-bold text-blue-600 dark:text-blue-400 mb-4">
          Facebook Video Downloader
        </h1>
        <p className="text-xl md:text-2xl text-gray-700 dark:text-gray-300">
          Download your favorite Facebook videos easily and for free.
        </p>
      </header>

      {/* Main Download Section */}
      <main className="w-full max-w-xl bg-white dark:bg-gray-900 rounded-lg shadow-md dark:shadow-lg p-6 md:p-8 mx-4">
        <div className="mb-6">
          <label htmlFor="videoUrl" className="block text-lg font-medium text-gray-800 dark:text-gray-200 mb-2">
            Paste Facebook Video URL here:
          </label>
          <input
            type="text"
            id="videoUrl"
            className="w-full px-4 py-3 rounded-md border border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 text-gray-900 dark:text-gray-100 placeholder-gray-500 dark:placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-blue-500 dark:focus:ring-blue-400 focus:border-blue-500 dark:focus:border-blue-400 transition-colors duration-300"
            placeholder="e.g., https://www.facebook.com/watch/?v=..."
            value={videoUrl}
            onChange={handleInputChange}
            disabled={isLoading} // Disable input while loading
          />
        </div>

        {/* Button calls the function that fetches and navigates */}
        <button
          onClick={handleDownloadAndNavigate} // Call the combined function
          className="w-full bg-blue-600 hover:bg-blue-700 dark:bg-blue-700 dark:hover:bg-blue-600 text-white font-bold py-3 px-4 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-opacity-50 transition-colors duration-300 disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center"
          disabled={isLoading || !videoUrl.trim()} // Disable button if loading or input is empty
        >
          {isLoading ? (
            <>
              {/* Loading Spinner */}
              <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
              </svg>
              Processing...
            </>
          ) : (
            'Download Video'
          )}
        </button>

        {/* Error Display - Shown only on homepage if fetch failed */}
        {error && (
          <div className="mt-4 p-3 bg-red-100 dark:bg-red-900 border border-red-400 dark:border-red-700 text-red-700 dark:text-red-300 rounded-md text-center">
            {error}
          </div>
        )}

        {/* Basic How-To / Disclaimer - Shown initially */}
         {!isLoading && !error && resultsOptions.length === 0 && !resultsThumbnailUrl && (
            <div className="mt-6 text-center text-gray-500 dark:text-gray-400 text-sm">
                <p>Enter the full URL of the Facebook video you want to download.</p>
                <p className="mt-2 text-xs">Please ensure you have the necessary permissions to download the video. Downloads are intended for personal offline use only.</p>
            </div>
        )}
      </main>
    </div>
  );
}

export default App;
